package app.veyra;
import android.app.*;import android.os.Bundle;import android.widget.*;
public final class SearchFiltersActivity extends Activity {
 private String editingProfile;private LinearLayout root;private EditText from,to,rating,genre,language;private Spinner kind;
 private EditText field(String label,String value,boolean number){root.addView(Ui.text(this,label,14,Ui.INK));EditText e=new EditText(this);e.setText(value);e.setTextColor(Ui.INK);e.setSingleLine(true);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(number?4:80)});if(number)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);root.addView(e);return e;}
 public void onCreate(Bundle saved){super.onCreate(saved);editingProfile=ProfileStore.id(this);Ui.configure(this);root=Ui.column(this);Button back=Ui.quiet(this,"‹  Back");back.setOnClickListener(v->finish());root.addView(back);root.addView(Ui.text(this,"Narrow it down.",30,Ui.INK));root.addView(Ui.text(this,"Filters use the metadata supplied on each results page. Titles with missing metadata won’t match an active filter. Browse more pages to find additional matches.",14,Ui.MUTED));SearchFilters.Criteria f=SearchFilters.read(this);from=field("Year from · blank for any",f.from==0?"":""+f.from,true);to=field("Year to · blank for any",f.to==0?"":""+f.to,true);rating=field("Minimum rating · 0 to 10",f.rating==0?"":""+f.rating,true);genre=field("Genre contains",f.genre,false);language=field("Language contains",f.language,false);root.addView(Ui.text(this,"Title type",14,Ui.INK));kind=new Spinner(this);kind.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"All titles","Movies & series","Shorts"}));kind.setSelection(f.kind.equals("short")?2:f.kind.equals("movie")?1:0);root.addView(kind);TextView error=Ui.text(this,"",14,0xffffb4a8);root.addView(error);Button apply=Ui.primary(this,"Apply filters");apply.setOnClickListener(v->{try{int start=value(from),end=value(to);if(start>9999||end>9999)throw new IllegalArgumentException();SearchFilters.save(this,new SearchFilters.Criteria(start,end,value(rating),genre.getText().toString(),language.getText().toString(),new String[]{"all","movie","short"}[kind.getSelectedItemPosition()]));setResult(RESULT_OK);finish();}catch(Exception e){error.setText("Check the year range and use a rating from 0 to 10.");}});root.addView(apply);Button clear=Ui.quiet(this,"Clear filters");clear.setOnClickListener(v->{SearchFilters.save(this,new SearchFilters.Criteria(0,0,0,"","","all"));setResult(RESULT_OK);finish();});root.addView(clear);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);Ui.insets(this,scroll,20);}
 protected void onResume(){super.onResume();if(!editingProfile.equals(ProfileStore.id(this)))recreate();}
 private int value(EditText field){String text=field.getText().toString().trim();return text.isEmpty()?0:Integer.parseInt(text);}
}
